/**
 * Ownership handover offers. Every read is filtered by `orgId`.
 */
import { and, desc, eq, or } from "drizzle-orm";
import { newId } from "@/lib/id";
import { getDb, ownershipHandovers } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { brandId, brandStamp, brandStampOrNull } from "./_mappers";
import type { OwnershipHandoverRow } from "@/server/db";
import type { OrgId, UserId } from "@/types/common";
import type {
  OwnershipHandover,
  OwnershipHandoverStatus,
} from "@/types/organization";

/** An offer stays actionable for exactly this long. */
export const HANDOVER_TTL_MS = 7 * 24 * 60 * 60 * 1000;

function toHandover(row: OwnershipHandoverRow): OwnershipHandover {
  return {
    id: row.id,
    orgId: brandId<OrgId>(row.orgId),
    fromUserId: brandId<UserId>(row.fromUserId),
    toUserId: brandId<UserId>(row.toUserId),
    status: row.status,
    expiresAt: brandStamp(row.expiresAt),
    createdAt: brandStamp(row.createdAt),
    resolvedAt: brandStampOrNull(row.resolvedAt),
  };
}

/** True once the offer can no longer be acted on. */
export function isLapsed(handover: OwnershipHandover, now: Date): boolean {
  return now.getTime() >= new Date(handover.expiresAt).getTime();
}

/** The newest row still marked pending, lapsed or not. */
export async function findPending(
  orgId: OrgId,
): Promise<OwnershipHandover | null> {
  const row = getDb()
    .select()
    .from(ownershipHandovers)
    .where(
      and(
        eq(ownershipHandovers.orgId, orgId),
        eq(ownershipHandovers.status, "pending"),
      ),
    )
    .orderBy(desc(ownershipHandovers.createdAt))
    .get();
  return row ? toHandover(row) : null;
}

export async function insertHandover(
  orgId: OrgId,
  fromUserId: UserId,
  toUserId: UserId,
  now: Date,
): Promise<OwnershipHandover> {
  const row = getDb()
    .insert(ownershipHandovers)
    .values({
      id: newId(),
      orgId,
      fromUserId,
      toUserId,
      status: "pending",
      expiresAt: toIsoTimestamp(new Date(now.getTime() + HANDOVER_TTL_MS)),
      createdAt: toIsoTimestamp(now),
      resolvedAt: null,
    })
    .returning()
    .get();
  return toHandover(row);
}

export async function resolveHandover(
  orgId: OrgId,
  id: string,
  status: OwnershipHandoverStatus,
  resolvedAt: Date,
): Promise<OwnershipHandover> {
  const row = getDb()
    .update(ownershipHandovers)
    .set({ status, resolvedAt: toIsoTimestamp(resolvedAt) })
    .where(and(eq(ownershipHandovers.orgId, orgId), eq(ownershipHandovers.id, id)))
    .returning()
    .get();
  if (!row) throw new Error(`Ownership handover ${id} not found in org ${orgId}`);
  return toHandover(row);
}

/** Withdraws every open offer that names `userId` on either side. */
export async function cancelPendingInvolving(
  orgId: OrgId,
  userId: UserId,
): Promise<void> {
  getDb()
    .update(ownershipHandovers)
    .set({ status: "canceled", resolvedAt: toIsoTimestamp(new Date()) })
    .where(
      and(
        eq(ownershipHandovers.orgId, orgId),
        eq(ownershipHandovers.status, "pending"),
        or(
          eq(ownershipHandovers.fromUserId, userId),
          eq(ownershipHandovers.toUserId, userId),
        ),
      ),
    )
    .run();
}
EOF
