function assertRecordedOwner(actor: Actor, org: Organization): void {
  if (actor.isPlatformStaff === true || actor.userId === org.ownerId) return;
  throw new PermissionDeniedError("org:update", {
    allowed: false,
    action: "org:update",
    resourceKind: "organization",
    reason: "denied_by_role",
  });
}

/** The open offer, or null. A lapsed offer is not open. */
async function findOpenHandover(orgId: OrgId): Promise<OwnershipHandover | null> {
  const pending = await handoverRepo.findPending(orgId);
  if (pending === null || handoverRepo.isLapsed(pending, new Date())) return null;
  return pending;
}

/** The offer the offered member may act on: refuses anyone else and lapsed offers. */
async function requireOfferedTo(actor: Actor, orgId: OrgId): Promise<OwnershipHandover> {
  const pending = await handoverRepo.findPending(orgId);
  if (pending === null || pending.toUserId !== actor.userId) {
    throw new OwnershipHandoverError("nothing_pending");
  }
  if (handoverRepo.isLapsed(pending, new Date())) {
    throw new OwnershipHandoverError("expired");
  }
  return pending;
}

export async function initiateOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
  toUserId: UserId,
): Promise<OwnershipHandover> {
  assertOrgScope(actor, orgId);
  const org = requireFound(await orgRepo.findOrgById(orgId), "Organization", orgId);
  assertRecordedOwner(actor, org);

  if (toUserId === org.ownerId || toUserId === actor.userId) {
    throw new OwnershipHandoverError("self");
  }

  const target = await memberRepo.findMember(orgId, toUserId);
  if (target === null || target.status !== "active") {
    throw new NotFoundError("Member", toUserId);
  }

  if ((await findOpenHandover(orgId)) !== null) {
    throw new OwnershipHandoverError("pending_exists");
  }

  const now = new Date();
  // A lapsed offer is still marked pending; retire it before the new one lands.
  const stale = await handoverRepo.findPending(orgId);
  if (stale !== null) {
    await handoverRepo.resolveHandover(
      orgId,
      stale.id,
      "expired",
      new Date(stale.expiresAt),
    );
  }

  const handover = await handoverRepo.insertHandover(
    orgId,
    org.ownerId,
    toUserId,
    now,
  );

  await notify(orgId, "ownership_handover", [toUserId], {
    title: "Ownership of the workspace was offered to you",
    body: `${org.name} can be handed over to you; accept before ${handover.expiresAt}`,
    href: "/settings/organization",
    actorId: actor.userId,
  });

  return handover;
}

export async function acceptOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<Organization> {
  assertOrgScope(actor, orgId);
  const handover = await requireOfferedTo(actor, orgId);

  const incoming = requireFound(
    await memberRepo.findMember(orgId, handover.toUserId),
    "Member",
    handover.toUserId,
  );
  const outgoing = await memberRepo.findMember(orgId, handover.fromUserId);

  // Promote first so the workspace has an owner at every instant.
  if (incoming.role !== "owner") {
    await memberRepo.updateMemberRole(orgId, incoming.id, "owner");
    await emit("member.role_changed", {
      ...actorEnvelope(actor),
      memberId: incoming.id,
      from: incoming.role,
      to: "owner",
    });
  }

  const org = await orgRepo.setOrgOwner(orgId, handover.toUserId);

  if (outgoing !== null && outgoing.role === "owner") {
    await memberRepo.updateMemberRole(orgId, outgoing.id, "admin");
    await emit("member.role_changed", {
      ...actorEnvelope(actor),
      memberId: outgoing.id,
      from: "owner",
      to: "admin",
    });
  }

  await handoverRepo.resolveHandover(orgId, handover.id, "accepted", new Date());

  await emit("organization.ownership_transferred", {
    ...actorEnvelope(actor),
    fromUserId: handover.fromUserId,
    toUserId: handover.toUserId,
  });

  return org;
}

export async function declineOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<OwnershipHandover> {
  assertOrgScope(actor, orgId);
  const handover = await requireOfferedTo(actor, orgId);
  return handoverRepo.resolveHandover(orgId, handover.id, "declined", new Date());
}

export async function cancelOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<OwnershipHandover> {
  assertOrgScope(actor, orgId);
  const org = requireFound(await orgRepo.findOrgById(orgId), "Organization", orgId);
  assertRecordedOwner(actor, org);

  const open = await findOpenHandover(orgId);
  if (open === null) throw new OwnershipHandoverError("nothing_pending");

  return handoverRepo.resolveHandover(orgId, open.id, "canceled", new Date());
}

export async function getPendingOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<OwnershipHandover | null> {
  assertOrgScope(actor, orgId);
  assertCan(actor, "org:read", orgResource(orgId));
  return findOpenHandover(orgId);
}
