/**
 * Organization creation, settings updates and deletion; seeds the owner membership and the free subscription.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, emit, uniqueSlug, assertValidSlug
 */
import { OwnershipHandoverError } from "@/lib/errors";
import { emit } from "@/lib/event-bus";
import { assertCan, PermissionDeniedError } from "@/lib/permissions";
import { assertValidSlug, uniqueSlug } from "@/lib/slug";
import { assertOrgScope } from "@/lib/tenant";
import * as memberRepo from "@/server/repositories/member-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as handoverRepo from "@/server/repositories/ownership-handover-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as subscriptionRepo from "@/server/repositories/subscription-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import { record } from "./activity-service";
import { notify } from "./notification-service";
import {
  actorEnvelope,
  envelope,
  NotFoundError,
  orgResource,
  requireFound,
} from "./_support";
import type {
  CreateOrganizationInput,
  DeleteOrganizationInput,
  UpdateOrganizationInput,
} from "@/schemas/organization";
import type { OrgId, UserId } from "@/types/common";
import type { Actor } from "@/types/member";
import type {
  Organization,
  OrganizationSummary,
  OwnershipHandover,
} from "@/types/organization";

/**
 * Creates an organization and everything it cannot exist without: the owner's
 * membership row and a subscription. Sign-up and "create another workspace"
 * both land here, which is why it takes a bare `ownerId` rather than an
 * `Actor` — there is no membership to build one from yet.
 */
export async function createOrganization(
  ownerId: UserId,
  input: CreateOrganizationInput,
): Promise<Organization> {
  assertValidSlug(input.slug);

  const taken = await orgRepo.listTakenOrgSlugs(input.slug);
  const slug = uniqueSlug(input.slug, taken);

  const org = await orgRepo.insertOrg({ ...input, slug }, ownerId);

  const owner = await memberRepo.insertMember(org.id, ownerId, "owner", null);
  await subscriptionRepo.insertSubscription(org.id, input.plan, "monthly");
  await usageRepo.recomputeUsage(org.id);

  await emit("member.joined", {
    ...envelope(org.id, ownerId),
    memberId: owner.id,
    userId: ownerId,
    role: owner.role,
  });

  return org;
}

export async function updateOrganization(
  actor: Actor,
  input: UpdateOrganizationInput,
): Promise<Organization> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "org:update", orgResource(input.orgId));

  const updated = await orgRepo.updateOrg(input.orgId, input);

  // Settings changes are audited directly: the event bus has no
  // `organization.updated` key, and inventing one would widen the contract.
  await record(input.orgId, "organization.updated", {
    actorId: actor.userId,
    subjectKind: "organization",
    subjectId: updated.id,
    projectId: null,
    summary: `${updated.name} settings updated`,
  });

  return updated;
}

/**
 * Deletion is a soft delete guarded by a typed confirmation, the same shape
 * GitHub uses: the caller has to retype the slug.
 */
export async function deleteOrganization(
  actor: Actor,
  input: DeleteOrganizationInput,
): Promise<Organization> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "org:delete", orgResource(input.orgId));

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );

  if (org.slug !== input.confirmSlug) {
    throw new Error("The confirmation does not match this organization's slug");
  }

  return orgRepo.archiveOrg(input.orgId);
}

/** The header/shell payload: the org plus the counters the sidebar shows. */
export async function getOrganizationSummary(
  actor: Actor,
  orgId: OrgId,
): Promise<OrganizationSummary> {
  assertOrgScope(actor, orgId);
  assertCan(actor, "org:read", orgResource(orgId));

  const organization = requireFound(
    await orgRepo.findOrgById(orgId),
    "Organization",
    orgId,
  );

  return {
    organization,
    usage: await usageRepo.getUsage(orgId),
    memberCount: await memberRepo.countActiveMembers(orgId),
    projectCount: await projectRepo.countProjects(orgId),
  };
}

/** The org switcher's list; no `Actor` exists until one is chosen. */
export async function listOrganizationsForUser(
  userId: UserId,
): Promise<readonly Organization[]> {
  return orgRepo.listOrgsForUser(userId);
}

export async function resolveOrgBySlug(
  slug: string,
): Promise<Organization | null> {
  return orgRepo.findOrgBySlug(slug);
}

function assertRecordedOwner(actor: Actor, org: Organization): void {
  if (actor.isPlatformStaff === true || actor.userId === org.ownerId) return;
  throw new PermissionDeniedError("org:update", {
    allowed: false,
    action: "org:update",
    resourceKind: "organization",
    reason: "denied_by_role",
  });
}

/** The open offer, or null. A lapsed offer is not open. */
async function findOpenHandover(orgId: OrgId): Promise<OwnershipHandover | null> {
  const pending = await handoverRepo.findPending(orgId);
  if (pending === null || handoverRepo.isLapsed(pending, new Date())) return null;
  return pending;
}

/** The offer the offered member may act on: refuses anyone else and lapsed offers. */
async function requireOfferedTo(actor: Actor, orgId: OrgId): Promise<OwnershipHandover> {
  const pending = await handoverRepo.findPending(orgId);
  if (pending === null || pending.toUserId !== actor.userId) {
    throw new OwnershipHandoverError("nothing_pending");
  }
  if (handoverRepo.isLapsed(pending, new Date())) {
    throw new OwnershipHandoverError("expired");
  }
  return pending;
}

export async function initiateOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
  toUserId: UserId,
): Promise<OwnershipHandover> {
  assertOrgScope(actor, orgId);
  const org = requireFound(await orgRepo.findOrgById(orgId), "Organization", orgId);
  assertRecordedOwner(actor, org);

  if (toUserId === org.ownerId || toUserId === actor.userId) {
    throw new OwnershipHandoverError("self");
  }

  const target = await memberRepo.findMember(orgId, toUserId);
  if (target === null || target.status !== "active") {
    throw new NotFoundError("Member", toUserId);
  }

  if ((await findOpenHandover(orgId)) !== null) {
    throw new OwnershipHandoverError("pending_exists");
  }

  const now = new Date();
  // A lapsed offer is still marked pending; retire it before the new one lands.
  const stale = await handoverRepo.findPending(orgId);
  if (stale !== null) {
    await handoverRepo.resolveHandover(
      orgId,
      stale.id,
      "expired",
      new Date(stale.expiresAt),
    );
  }

  const handover = await handoverRepo.insertHandover(
    orgId,
    org.ownerId,
    toUserId,
    now,
  );

  await notify(orgId, "ownership_handover", [toUserId], {
    title: "Ownership of the workspace was offered to you",
    body: `${org.name} can be handed over to you; accept before ${handover.expiresAt}`,
    href: "/settings/organization",
    actorId: actor.userId,
  });

  return handover;
}

export async function acceptOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<Organization> {
  assertOrgScope(actor, orgId);
  const handover = await requireOfferedTo(actor, orgId);

  const incoming = requireFound(
    await memberRepo.findMember(orgId, handover.toUserId),
    "Member",
    handover.toUserId,
  );
  const outgoing = await memberRepo.findMember(orgId, handover.fromUserId);

  // Promote first so the workspace has an owner at every instant.
  if (incoming.role !== "owner") {
    await memberRepo.updateMemberRole(orgId, incoming.id, "owner");
    await emit("member.role_changed", {
      ...actorEnvelope(actor),
      memberId: incoming.id,
      from: incoming.role,
      to: "owner",
    });
  }

  const org = await orgRepo.setOrgOwner(orgId, handover.toUserId);

  if (outgoing !== null && outgoing.role === "owner") {
    await memberRepo.updateMemberRole(orgId, outgoing.id, "admin");
    await emit("member.role_changed", {
      ...actorEnvelope(actor),
      memberId: outgoing.id,
      from: "owner",
      to: "admin",
    });
  }

  await handoverRepo.resolveHandover(orgId, handover.id, "accepted", new Date());

  await emit("organization.ownership_transferred", {
    ...actorEnvelope(actor),
    fromUserId: handover.fromUserId,
    toUserId: handover.toUserId,
  });

  return org;
}

export async function declineOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<OwnershipHandover> {
  assertOrgScope(actor, orgId);
  const handover = await requireOfferedTo(actor, orgId);
  return handoverRepo.resolveHandover(orgId, handover.id, "declined", new Date());
}

export async function cancelOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<OwnershipHandover> {
  assertOrgScope(actor, orgId);
  const org = requireFound(await orgRepo.findOrgById(orgId), "Organization", orgId);
  assertRecordedOwner(actor, org);

  const open = await findOpenHandover(orgId);
  if (open === null) throw new OwnershipHandoverError("nothing_pending");

  return handoverRepo.resolveHandover(orgId, open.id, "canceled", new Date());
}

export async function getPendingOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<OwnershipHandover | null> {
  assertOrgScope(actor, orgId);
  assertCan(actor, "org:read", orgResource(orgId));
  return findOpenHandover(orgId);
}
